const ringOpacity = interpolate(ringFrame, [0, Math.max(1, ringDur)], [0.9, 0], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const ringThickness = interpolate(ringFrame, [0, Math.max(1, ringDur)], [30, 3], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const halfCirc = Math.PI * Math.max(1, ringRadius);

const particleCount = 120;
const particleEls = Array.from({length: particleCount}, function(_, i) {
  const s1 = srand(i * 7 + 13);
  const s2 = srand(i * 11 + 29);
  const s3 = srand(i * 17 + 41);
  const s4 = srand(i * 23 + 53);
  const angle = s1 * Math.PI * 2;
  const speed = 3 + s2 * 10;
  const spinRate = (s3 - 0.5) * 600;
  const size = 2 + s4 * 6;
  const pFrame = Math.max(0, frame - 6);
  const dist = speed * pFrame;
  const x = cx + Math.cos(angle) * dist;
  const y = cy + Math.sin(angle) * dist;
  const opacity = interpolate(pFrame, [0, 40], [1, 0], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const rotation = spinRate * (pFrame / fps);
  const color = i % 2 === 0 ? D.cyan : D.violet;
  return React.createElement('div', {
