      height: size,
      borderRadius: s4 > 0.5 ? '50%' : '2px',
      backgroundColor: color,
      opacity: opacity,
      transform: 'rotate(' + rotation + 'deg)',
      boxShadow: '0 0 6px ' + color
    }
  });
